/// The open tabs once `tab` is Ctrl/Cmd+clicked: opened alongside `open`, or
/// closed if it was open and isn't the only one; always in the order of the
/// tabs.
pub fn toggle_open(open: &[RibbonTab], tab: RibbonTab) -> Vec<RibbonTab> {
    let was_open = open.contains(&tab);
    if was_open && open.len() == 1 {
        return open.to_vec();
    }
    RibbonTab::ALL
        .into_iter()
        .filter(|candidate| {
            if *candidate == tab {
                !was_open
            } else {
                open.contains(candidate)
            }
        })
        .collect()
}

/// A group of related commands, titled along its left edge, reading bottom to
/// top, on a strip of its own.
fn group(
    label: &'static str,
    commands: Vec<(CommandSize, AnyElement)>,
    muted: Hsla,
    title_background: Hsla,
    font: &str,
) -> AnyElement {
    // Full buttons stand alone; slim ones side by side stack down, three to a
    // column, top aligned.
    let mut columns: Vec<AnyElement> = Vec::new();
    let mut stack: Vec<AnyElement> = Vec::new();
    let flush = |stack: &mut Vec<AnyElement>, columns: &mut Vec<AnyElement>| {
        if !stack.is_empty() {
            columns.push(
                v_flex()
                    .flex_none()
                    .gap(BODY_PADDING)
                    .children(stack.drain(..))
                    .into_any_element(),
            );
        }
    };
    for (size, element) in commands {
        match size {
            CommandSize::Full => {
                flush(&mut stack, &mut columns);
                // As tall as its content needs, and as tall as its group where
                // that leaves the room, within two and three slim buttons; the
                // button itself fills that.
                columns.push(
                    h_flex()
                        .flex_none()
                        .items_stretch()
                        .overflow_hidden()
                        .min_h(full_min())
                        .max_h(full_max())
                        .child(element)
                        .into_any_element(),
                );
            }
            CommandSize::Slim | CommandSize::Small => {
                if stack.len() == SLIM_STACK {
                    flush(&mut stack, &mut columns);
                }
                stack.push(element);
            }
        }
    }
    flush(&mut stack, &mut columns);
    // Lets UI tests find the group; inert in normal builds.
    gpui_kit::TestSupportExt::test_support(h_flex().id(label))
        .items_stretch()
        .gap(BODY_PADDING)
        .child(
            div()
                .relative()
                .flex()
                .flex_none()
                .items_center()
                .overflow_hidden()
                .w(GROUP_TITLE_WIDTH)
                .bg(title_background)
                .child(group_title(label, muted, font)),
        )
        .child(
            // Each command takes the height it needs; a full button grows into
            // its group's height where there is more of it, up to its own
            // limit.
            h_flex()
                .items_stretch()
                .py(BODY_PADDING)
                .gap(BODY_PADDING)
                .children(columns),
        )
        .into_any_element()
}

